mapper.select:
SELECT purchase_order_id, COUNT(DISTINCT sku_code) AS sku_count, COALESCE(SUM(quantity), 0) AS total_quantity, COALESCE(SUM(shipped_quantity), 0) AS total_shipped_quantity, COALESCE(SUM(received_quantity), 0) AS total_received_quantity FROM wms_purchase_order_item WHERE purchase_order_id IN
#{orderId}
GROUP BY purchase_order_id

update.foreach:
UPDATE wms_purchase_order_item
SET received_quantity = IFNULL(received_quantity, 0) + #{item.quantity}
WHERE id = #{item.purchaseOrderItemId}

mapper.update:
UPDATE wms_purchase_order_item
SET shipped_quantity = IFNULL(shipped_quantity, 0) + #{quantity}
WHERE id = #{itemId}
  AND (quantity - IFNULL(shipped_quantity, 0)) >= #{quantity}

UPDATE wms_purchase_order_item
SET received_quantity = IFNULL(received_quantity, 0) + #{quantity}
WHERE id = #{itemId}
  AND (IFNULL(shipped_quantity, 0) - IFNULL(received_quantity, 0)) >= #{quantity}
